+    const mv = typeof e.move === 'string' ? MOVES[e.move] : e.move;
+    if (!mv) throw new Error(`没有这个舞步：${e.move}`);
+    if (mv.isClip) return mv.solve(u + (e.offset || 0), dancer, e);
+    return dancer.solver.solve(normalizeSpec(mv(u + (e.offset || 0), e), e));
+  };
