+    const protoClone = Object.getPrototypeOf(m).clone;
+    m.clone = function () {
+      const c = protoClone.call(this);
+      c.userData = { ...c.userData, dancePatches: [], dancePatched: false };
+      for (const p of this.userData.dancePatches) addShaderPatch(c, p);
+      return c;
+    };
+  }
