+  const face = canvas();
+  const fctx = face.getContext('2d');
+
+  function headMatrix(p, by) {
+    const nod = p.nod || 0;
+    return mul(T(px + (p.dx || 0), py + (p.dy || 0) + nod + by),
+      mul(R(p.roll || 0), mul(S(1, 1 - nod * 0.004), T(-px, -py))));
