+    const bAmp = breath.amp ?? 3, bPer = breath.period ?? 3.8;
+    const breathAt = tt => -bAmp * 0.5 * (1 - Math.cos(2 * Math.PI * tt / bPer));  // 吸气时上移（负）
+    const span = H - bodyTop;
+    const bodyShift = (yy, by) => by * clamp((H - yy) / span);
